          "A associação de Tol Eressëa à língua dos Teleri deve ser descrita com precisão. Os Teleri de Aman utilizavam o telerin; o quenya também era conhecido e preservado entre os Elfos e os Númenóreanos, mas não é correto tratar essas línguas como idênticas.",
