      observations: {
        heading: "Observações de precisão canônica",
        items: [
          "Gondolin significa tradicionalmente Rocha Oculta, enquanto Ondolindë é seu nome em quenya, associado à ideia de Pedra da Música das Águas.",
          "Gondolin foi construída sobre Amon Gwareth, no centro do Vale de Tumladen.",
          "Turgon fundou Gondolin com a orientação de Ulmo, que desejava estabelecer um refúgio oculto para os Noldor.",
          "A cidade foi inspirada em Tirion sobre Túna, preservando a memória das cidades élficas de Aman.",
          "Os Sete Portões pertenciam ao sistema defensivo do Caminho Oculto, não eram simplesmente sete entradas distribuídas pelas muralhas da cidade.",
          "Tuor chegou a Gondolin acompanhado por Voronwë, levando uma advertência de Ulmo.",
          "Idril preparou uma passagem secreta, permitindo a fuga de parte dos habitantes durante a destruição da cidade.",
          "Maeglin revelou a localização de Gondolin a Morgoth, contribuindo para sua queda.",
          "Eärendil nasceu em Gondolin, e sua linhagem alcançou Elrond e Elros.",
          "As casas de guerreiros de Gondolin são descritas principalmente nas versões antigas da história, não devendo todos os seus detalhes ser tratados como definitivos.",
        ],
      },
